import type { ReactElement, ReactNode } from 'react'
import { Card, CardPanel, type CardProps } from '../../components/card'
import { cn } from '../../lib/utils'

export interface KanbanCardProps extends Omit<CardProps, 'density'> {
  dimmed?: boolean
  contentClassName?: string
  renderContent?: boolean
  children: ReactNode
}

export function KanbanCard({
  children,
  className,
  contentClassName,
  dimmed = false,
  render = <article />,
  renderContent = true,
  ...props
}: KanbanCardProps): ReactElement {
  return (
    <Card className={cn(dimmed && 'opacity-70', className)} density="sm" render={render} {...props}>
      {renderContent ? <CardPanel className={contentClassName}>{children}</CardPanel> : children}
    </Card>
  )
}

import type { UniqueIdentifier } from '@dnd-kit/core'
import { useDroppable } from '@dnd-kit/core'
import { SortableContext, verticalListSortingStrategy } from '@dnd-kit/sortable'
import type { ReactNode } from 'react'
import { useId, useMemo } from 'react'
import { ScrollArea } from '../../components/scroll-area'
import { Text } from '../../components/text'
import { cn } from '../../lib/utils'

import { createColumnDropId } from '../lib/drag-and-drop'
import type { KanbanColumnData } from '../types'
import { KanbanBadge } from './kanban-badge'
import { SortableKanbanCard } from './sortable-kanban-card'

export interface KanbanColumnProps<TCard = unknown> {
  column: KanbanColumnData<TCard>
  renderCard: (card: TCard) => ReactNode
  getKey: (card: TCard) => string | number
  emptyLabel?: string
  className?: string
  getCardDragId?: (card: TCard) => UniqueIdentifier
  getCardLabel?: (card: TCard) => string
  sortableCards?: boolean
}

function KanbanEmptyState({
  children,
  className,
}: Readonly<{ children: ReactNode; className?: string }>) {
  return (
    <div
      className={cn(
        'rounded-md border border-dashed px-3 py-6 text-center text-muted-foreground text-sm',
        className,
      )}
    >
      {children}
    </div>
  )
}

function KanbanColumnHeader<TCard>({
  column,
  titleId,
}: Readonly<{ column: KanbanColumnData<TCard>; titleId: string }>) {
  return (
    <header className="mb-3 flex shrink-0 items-center justify-between gap-3 px-3 pt-3">
      <div className="flex min-w-0 items-center gap-2">
        <Text
          leading="none"
          render={<h2 id={titleId}>{column.title}</h2>}
          size="sm"
          truncate
          weight="semibold"
        />
        <KanbanBadge tone="neutral">{column.count}</KanbanBadge>
      </div>
    </header>
  )
}

interface KanbanColumnCardsProps<TCard> {
  cardDragIds: UniqueIdentifier[]
  column: KanbanColumnData<TCard>
  emptyLabel: string
  getCardDragId?: (card: TCard) => UniqueIdentifier
  getCardLabel: (card: TCard) => string
  getKey: (card: TCard) => string | number
  renderCard: (card: TCard) => ReactNode
  sortableCards: boolean
}

function KanbanColumnCards<TCard>({
  cardDragIds,
  column,
  emptyLabel,
  getCardDragId,
  getCardLabel,
  getKey,
  renderCard,
  sortableCards,
}: KanbanColumnCardsProps<TCard>) {
  if (!column.cards.length) {
    return <KanbanEmptyState className="bg-card/60 py-10">{emptyLabel}</KanbanEmptyState>
  }

  if (!sortableCards || !getCardDragId) {
    return column.cards.map((card) => <div key={getKey(card)}>{renderCard(card)}</div>)
  }

  return (
    <SortableContext items={cardDragIds} strategy={verticalListSortingStrategy}>
      {column.cards.map((card) => (
        <SortableKanbanCard
          columnId={column.id}
          dragLabel={`Mover card ${getCardLabel(card)}`}
          id={getCardDragId(card)}
          key={getKey(card)}
        >
          {renderCard(card)}
        </SortableKanbanCard>
      ))}
    </SortableContext>
  )
}

export function KanbanColumn<TCard>({
  column,
  renderCard,
  getKey,
  emptyLabel = 'Nenhum item nesta coluna.',
  className,
  getCardDragId,
  getCardLabel = (card) => String(getKey(card)),
  sortableCards = false,
}: KanbanColumnProps<TCard>) {
  const instanceId = useId()
  const titleId = `kanban-column-title-${instanceId}`
  const { setNodeRef } = useDroppable({
    id: createColumnDropId(column.id, instanceId),
    data: { columnId: column.id, type: 'column' },
    disabled: !sortableCards,
  })
  const cardDragIds = useMemo(
    () => (sortableCards && getCardDragId ? column.cards.map(getCardDragId) : []),
    [column.cards, getCardDragId, sortableCards],
  )

  return (
    <section
      aria-labelledby={titleId}
      className={cn(
        'flex h-full min-h-0 flex-col rounded-lg bg-card/30 shadow-black/5 shadow-inner',
        className,
      )}
    >
      <KanbanColumnHeader column={column} titleId={titleId} />

      <ScrollArea className="min-h-0 flex-1" fill scrollbarGutter scrollFade>
        <div ref={setNodeRef} className="grid h-full min-h-full content-start gap-2 px-2 pb-2">
          <KanbanColumnCards
            cardDragIds={cardDragIds}
            column={column}
            emptyLabel={emptyLabel}
            getCardDragId={getCardDragId}
            getCardLabel={getCardLabel}
            getKey={getKey}
            renderCard={renderCard}
            sortableCards={sortableCards}
          />
        </div>
      </ScrollArea>
    </section>
  )
}

import { useId } from 'react'
import { ScrollArea } from '../../components/scroll-area'
import { cn } from '../../lib/utils'

import type { KanbanStageOption } from '../types'

export interface KanbanStageSelectorProps {
  id?: string
  label?: string
  stages: KanbanStageOption[]
  value: string
  onValueChange: (value: string) => void
  hint?: string
}

export function KanbanStageSelector({
  id,
  label = 'Etapa',
  stages,
  value,
  onValueChange,
  hint,
}: KanbanStageSelectorProps) {
  const generatedId = useId()
  const selectorId = id ?? `kanban-stage-${generatedId}`

  return (
    <div className="md:hidden">
      <div className="mb-1.5 font-medium text-muted-foreground text-xs" id={`${selectorId}-label`}>
        {label}
      </div>
      <ScrollArea aria-labelledby={`${selectorId}-label`} className="h-9" scrollbarGutter>
        <div className="flex w-max gap-1">
          {stages.map((stage) => {
            const selected = stage.value === value
            return (
              <button
                aria-pressed={selected}
                className={cn(
                  'h-8 shrink-0 rounded-md px-2.5 font-medium text-sm outline-none transition-colors focus-visible:ring-2 focus-visible:ring-ring',
                  selected
                    ? 'bg-card text-foreground'
                    : 'bg-card/45 text-muted-foreground hover:bg-card/70 hover:text-foreground',
                )}
                key={stage.value}
                onClick={() => onValueChange(stage.value)}
                type="button"
              >
                {stage.label}
              </button>
            )
          })}
        </div>
      </ScrollArea>
      {hint ? <p className="mt-2 text-muted-foreground text-xs">{hint}</p> : null}
    </div>
  )
}

import { closestCorners, DndContext, DragOverlay } from '@dnd-kit/core'
import type { ReactNode } from 'react'
import { useMemo } from 'react'
import { ScrollArea } from '../../components/scroll-area'

import { useActiveColumnId } from '../hooks/use-active-column-id'
import { useHorizontalDragScroll } from '../hooks/use-horizontal-drag-scroll'
import { useKanbanDragAndDrop } from '../hooks/use-kanban-drag-and-drop'
import type { KanbanCardMove, KanbanColumnData, KanbanStageOption } from '../types'
import { KanbanColumn } from './kanban-column'
import { KanbanStageSelector } from './kanban-stage-selector'

export interface KanbanViewProps<TCard = unknown> {
  columns: KanbanColumnData<TCard>[]
  renderCard: (card: TCard) => ReactNode
  getKey: (card: TCard) => string | number
  getCardLabel?: (card: TCard) => string
  emptyColumnLabel?: string
  mobileStageHint?: string
  onMoveCard?: (move: KanbanCardMove<TCard>) => boolean
}

export function KanbanView<TCard>({
  columns,
  renderCard,
  getKey,
  getCardLabel,
  emptyColumnLabel,
  mobileStageHint,
  onMoveCard,
}: KanbanViewProps<TCard>) {
  const [activeColumnId, setActiveColumnId] = useActiveColumnId(columns)
  const {
    activeCard,
    cardDragEnabled,
    getCardDragId,
    handleDragCancel,
    handleDragEnd,
    handleDragOver,
    handleDragStart,
    sensors,
    visibleColumns,
  } = useKanbanDragAndDrop({ columns, getKey, onMoveCard })
  const { isDragging: isBoardDragging, viewportProps } = useHorizontalDragScroll()
  const stageOptions = useMemo(() => createStageOptions(columns), [columns])
  const activeColumn = useMemo(
    () => visibleColumns.find((column) => column.id === activeColumnId) ?? visibleColumns[0],
    [activeColumnId, visibleColumns],
  )
  const columnProps = {
    emptyLabel: emptyColumnLabel,
    getCardLabel,
    getCardDragId,
    getKey,
    renderCard,
    sortableCards: cardDragEnabled,
  }

  return (
    <div className="h-full min-h-0">
      <DndContext
        collisionDetection={closestCorners}
        onDragCancel={handleDragCancel}
        onDragEnd={handleDragEnd}
        onDragOver={handleDragOver}
        onDragStart={handleDragStart}
        sensors={sensors}
      >
        <div className="flex h-full min-h-0 flex-col gap-2">
          <KanbanStageSelector
            hint={mobileStageHint}
            onValueChange={setActiveColumnId}
            stages={stageOptions}
            value={activeColumnId}
          />

          <div className="grid min-h-0 flex-1 gap-2 md:hidden">
            {activeColumn ? (
              <KanbanColumn column={activeColumn} {...columnProps} sortableCards={false} />
            ) : null}
          </div>

          <ScrollArea
            className="hidden min-h-0 flex-1 md:block"
            fill
            scrollbarGutter
            scrollFade
            viewportProps={{
              ...viewportProps,
              className: isBoardDragging ? 'cursor-grabbing select-none' : 'cursor-grab',
              'data-kanban-board-viewport': '',
            }}
          >
            <div className="grid h-full min-h-full w-max auto-cols-[minmax(19rem,22rem)] grid-flow-col gap-2">
              {visibleColumns.map((column) => (
                <KanbanColumn column={column} key={column.id} {...columnProps} />
              ))}
            </div>
          </ScrollArea>
        </div>

        <DragOverlay dropAnimation={null} zIndex={20}>
          {activeCard ? <div className="pointer-events-none">{renderCard(activeCard)}</div> : null}
        </DragOverlay>
      </DndContext>
    </div>
  )
}

function createStageOptions(columns: KanbanColumnData[]): KanbanStageOption[] {
  return columns.map((column) => ({
    label: `${column.title} · ${column.count}`,
    value: column.id,
  }))
}

import type { UniqueIdentifier } from '@dnd-kit/core'
import { useSortable } from '@dnd-kit/sortable'
import { CSS } from '@dnd-kit/utilities'
import type { CSSProperties, ReactNode } from 'react'

interface SortableKanbanCardProps {
  children: ReactNode
  columnId: string
  dragLabel: string
  id: UniqueIdentifier
}

export function SortableKanbanCard({ children, columnId, dragLabel, id }: SortableKanbanCardProps) {
  const { attributes, listeners, setNodeRef, transform } = useSortable({
    animateLayoutChanges: () => false,
    attributes: {
      role: 'region',
      roleDescription: 'card arrastável',
      tabIndex: 0,
    },
    data: { cardId: String(id), columnId, type: 'card' },
    id,
    transition: null,
  })
  const style: CSSProperties = {
    transform: CSS.Transform.toString(transform),
  }
  const { 'aria-pressed': _ariaPressed, role: _role, ...dragAttributes } = attributes

  return (
    <section
      aria-label={dragLabel}
      className="relative touch-none cursor-grab rounded-lg outline-none focus-visible:ring-2 focus-visible:ring-ring active:cursor-grabbing"
      data-kanban-card-draggable=""
      ref={setNodeRef}
      style={style}
      {...dragAttributes}
      {...listeners}
    >
      {children}
    </section>
  )
}

import { useEffect, useState } from 'react'

import type { KanbanColumnData } from '../types'

export function useActiveColumnId(columns: KanbanColumnData[]): [string, (id: string) => void] {
  const [activeColumnId, setActiveColumnId] = useState(columns[0]?.id ?? '')

  useEffect(() => {
    if (!columns.some((column) => column.id === activeColumnId)) {
      setActiveColumnId(columns[0]?.id ?? '')
    }
  }, [activeColumnId, columns])

  return [activeColumnId, setActiveColumnId]
}

import type { MouseEvent as ReactMouseEvent, PointerEvent as ReactPointerEvent } from 'react'
import { useCallback, useRef, useState } from 'react'

const DRAG_THRESHOLD = 8
const CLICK_SUPPRESSION_WINDOW_MS = 500
const EXCLUDED_TARGETS = [
  'a',
  'button',
  'input',
  'select',
  'textarea',
  '[contenteditable="true"]',
  '[role="button"]',
  '[role="link"]',
  '[role="menuitem"]',
  '[role="option"]',
  '[role="slider"]',
  '[data-kanban-card-draggable]',
  '[data-slot="scroll-area-scrollbar"]',
].join(',')

interface DragOrigin {
  pointerId: number
  scrollLeft: number
  x: number
  y: number
  dragging: boolean
}

interface ReleasedDrag {
  at: number
  x: number
  y: number
}

function isExcludedTarget(target: EventTarget | null): boolean {
  return target instanceof Element && target.closest(EXCLUDED_TARGETS) !== null
}

export function useHorizontalDragScroll() {
  const dragOriginRef = useRef<DragOrigin | null>(null)
  const releasedDragRef = useRef<ReleasedDrag | null>(null)
  const [isDragging, setIsDragging] = useState(false)

  const resetDrag = useCallback(() => {
    dragOriginRef.current = null
    setIsDragging(false)
  }, [])

  const handlePointerDown = useCallback((event: ReactPointerEvent<HTMLDivElement>) => {
    if (event.button !== 0 || !event.isPrimary || isExcludedTarget(event.target)) return

    releasedDragRef.current = null
    dragOriginRef.current = {
      dragging: false,
      pointerId: event.pointerId,
      scrollLeft: event.currentTarget.scrollLeft,
      x: event.clientX,
      y: event.clientY,
    }
  }, [])

  const handlePointerMove = useCallback((event: ReactPointerEvent<HTMLDivElement>) => {
    const origin = dragOriginRef.current
    if (!origin || origin.pointerId !== event.pointerId) return

    const deltaX = event.clientX - origin.x
    const deltaY = event.clientY - origin.y

    if (!origin.dragging) {
      if (Math.abs(deltaX) < DRAG_THRESHOLD && Math.abs(deltaY) < DRAG_THRESHOLD) return
      if (Math.abs(deltaX) <= Math.abs(deltaY)) {
        dragOriginRef.current = null
        return
      }

      origin.dragging = true
      event.currentTarget.setPointerCapture?.(event.pointerId)
      setIsDragging(true)
    }

    event.preventDefault()
    const maximumScrollLeft = Math.max(
      0,
      event.currentTarget.scrollWidth - event.currentTarget.clientWidth,
    )
    event.currentTarget.scrollLeft = Math.min(
      maximumScrollLeft,
      Math.max(0, origin.scrollLeft - deltaX),
    )
  }, [])

  const handlePointerEnd = useCallback(
    (event: ReactPointerEvent<HTMLDivElement>) => {
      const origin = dragOriginRef.current
      if (!origin || origin.pointerId !== event.pointerId) return

      if (origin.dragging) {
        releasedDragRef.current = {
          at: Date.now(),
          x: event.clientX,
          y: event.clientY,
        }
        if (event.currentTarget.hasPointerCapture?.(event.pointerId)) {
          event.currentTarget.releasePointerCapture(event.pointerId)
        }
      }

      resetDrag()
    },
    [resetDrag],
  )

  const handleClickCapture = useCallback((event: ReactMouseEvent<HTMLDivElement>) => {
    const releasedDrag = releasedDragRef.current
    if (!releasedDrag) return

    releasedDragRef.current = null
    const isReleasedDragClick =
      Date.now() - releasedDrag.at <= CLICK_SUPPRESSION_WINDOW_MS &&
      Math.abs(event.clientX - releasedDrag.x) <= 1 &&
      Math.abs(event.clientY - releasedDrag.y) <= 1

    if (isReleasedDragClick) {
      event.preventDefault()
      event.stopPropagation()
    }
  }, [])

  return {
    isDragging,
    viewportProps: {
      'data-drag-scrolling': isDragging ? '' : undefined,
      onClickCapture: handleClickCapture,
      onLostPointerCapture: resetDrag,
      onPointerCancel: handlePointerEnd,
      onPointerDown: handlePointerDown,
      onPointerMove: handlePointerMove,
      onPointerUp: handlePointerEnd,
    },
  }
}

import type { DragEndEvent, DragOverEvent, DragStartEvent } from '@dnd-kit/core'
import { KeyboardSensor, PointerSensor, useSensor, useSensors } from '@dnd-kit/core'
import { sortableKeyboardCoordinates } from '@dnd-kit/sortable'
import { useCallback, useEffect, useMemo, useRef, useState } from 'react'

import {
  createCardDragId,
  findCardLocation,
  moveCardToPreviewColumn,
  resolveCardMove,
  resolveTargetColumnId,
} from '../lib/drag-and-drop'
import type { KanbanCardMove, KanbanColumnData } from '../types'

interface UseKanbanDragAndDropOptions<TCard> {
  columns: KanbanColumnData<TCard>[]
  getKey: (card: TCard) => string | number
  onMoveCard?: (move: KanbanCardMove<TCard>) => boolean
}

interface PendingCardMove {
  cardDragId: string
  targetColumnId: string
}

export function useKanbanDragAndDrop<TCard>({
  columns,
  getKey,
  onMoveCard,
}: UseKanbanDragAndDropOptions<TCard>) {
  const [previewColumns, setPreviewColumns] = useState<KanbanColumnData<TCard>[] | null>(null)
  const [activeCard, setActiveCard] = useState<TCard | null>(null)
  const previewColumnsRef = useRef<KanbanColumnData<TCard>[] | null>(null)
  const sourceColumnIdRef = useRef<string | null>(null)
  const pendingCardMoveRef = useRef<PendingCardMove | null>(null)
  const sensors = useSensors(
    useSensor(PointerSensor, { activationConstraint: { distance: 6 } }),
    useSensor(KeyboardSensor, { coordinateGetter: sortableKeyboardCoordinates }),
  )

  const getCardDragId = useCallback((card: TCard) => createCardDragId(getKey(card)), [getKey])
  const cardsByDragId = useMemo(
    () =>
      new Map(
        columns.flatMap((column) =>
          column.cards.map((card) => [String(getCardDragId(card)), card] as const),
        ),
      ),
    [columns, getCardDragId],
  )

  const updatePreviewColumns = useCallback((nextColumns: KanbanColumnData<TCard>[] | null) => {
    previewColumnsRef.current = nextColumns
    setPreviewColumns(nextColumns)
  }, [])

  const resetDragState = useCallback(() => {
    pendingCardMoveRef.current = null
    sourceColumnIdRef.current = null
    setActiveCard(null)
    updatePreviewColumns(null)
  }, [updatePreviewColumns])

  useEffect(() => {
    const pendingCardMove = pendingCardMoveRef.current
    if (!pendingCardMove) return

    const cardLocation = findCardLocation(columns, pendingCardMove.cardDragId, getCardDragId)
    if (cardLocation?.columnId !== pendingCardMove.targetColumnId) return

    pendingCardMoveRef.current = null
    updatePreviewColumns(null)
  }, [columns, getCardDragId, updatePreviewColumns])

  const handleDragStart = useCallback(
    (event: DragStartEvent) => {
      const isCardDrag = event.active.data.current?.type === 'card'
      pendingCardMoveRef.current = null
      sourceColumnIdRef.current = isCardDrag
        ? String(event.active.data.current?.columnId ?? '')
        : null
      updatePreviewColumns(isCardDrag ? columns : null)
      setActiveCard(isCardDrag ? (cardsByDragId.get(String(event.active.id)) ?? null) : null)
    },
    [cardsByDragId, columns, updatePreviewColumns],
  )

  const handleDragOver = useCallback(
    (event: DragOverEvent) => {
      const { active, over } = event
      if (!over || active.data.current?.type !== 'card' || !onMoveCard) return

      const targetColumnId = resolveTargetColumnId(over.id, over.data.current)
      if (!targetColumnId) return
      const activeRect = active.rect?.current.translated ?? null
      const insertAfter =
        over.data.current?.type === 'card' &&
        activeRect !== null &&
        activeRect.top + activeRect.height / 2 > over.rect.top + over.rect.height / 2

      updatePreviewColumns(
        moveCardToPreviewColumn(
          previewColumnsRef.current ?? columns,
          String(active.id),
          targetColumnId,
          over.id,
          getCardDragId,
          insertAfter,
        ),
      )
    },
    [columns, getCardDragId, onMoveCard, updatePreviewColumns],
  )

  const handleDragEnd = useCallback(
    (event: DragEndEvent) => {
      const { active, over } = event
      if (!over) {
        resetDragState()
        return
      }

      const activeData = active.data.current
      const overData = over.data.current

      if (activeData?.type === 'card' && onMoveCard) {
        const activeDragId = String(active.id)
        const move = resolveCardMove({
          activeDragId,
          columns,
          getCardDragId,
          overData,
          overId: over.id,
          sourceColumnId: sourceColumnIdRef.current || String(activeData.columnId),
          visibleColumns: previewColumnsRef.current ?? columns,
        })

        if (move) {
          const moveAccepted = onMoveCard(move)

          sourceColumnIdRef.current = null
          setActiveCard(null)

          if (!moveAccepted) {
            updatePreviewColumns(null)
          } else {
            pendingCardMoveRef.current = {
              cardDragId: activeDragId,
              targetColumnId: move.targetColumnId,
            }
          }
          return
        }
      }

      resetDragState()
    },
    [columns, getCardDragId, onMoveCard, resetDragState, updatePreviewColumns],
  )

  return {
    activeCard,
    cardDragEnabled: Boolean(onMoveCard),
    getCardDragId,
    handleDragCancel: resetDragState,
    handleDragEnd,
    handleDragOver,
    handleDragStart,
    sensors,
    visibleColumns: previewColumns ?? columns,
  }
}

import type { UniqueIdentifier } from '@dnd-kit/core'

import type { KanbanCardMove, KanbanColumnData } from '../types'

const CARD_DRAG_PREFIX = 'kanban-card:'
const COLUMN_DROP_PREFIX = 'kanban-column:'

export interface CardLocation<TCard> {
  card: TCard
  cardIndex: number
  columnId: string
  columnIndex: number
}

export function createCardDragId(cardId: string | number): string {
  return `${CARD_DRAG_PREFIX}${String(cardId)}`
}

export function parseCardDragId(id: UniqueIdentifier): string {
  return String(id).replace(new RegExp(`^${CARD_DRAG_PREFIX}`), '')
}

export function createColumnDropId(columnId: string, instanceId?: string): string {
  const columnPart = encodeURIComponent(columnId)
  const instancePart = instanceId ? `:${encodeURIComponent(instanceId)}` : ''

  return `${COLUMN_DROP_PREFIX}${columnPart}${instancePart}`
}

export function parseColumnId(id: UniqueIdentifier): string {
  const value = String(id)

  if (!value.startsWith(COLUMN_DROP_PREFIX)) return ''

  const encodedColumnId = value.slice(COLUMN_DROP_PREFIX.length).split(':', 1)[0] ?? ''

  try {
    return decodeURIComponent(encodedColumnId)
  } catch {
    return encodedColumnId
  }
}

export function resolveTargetColumnId(
  overId: UniqueIdentifier,
  overData: Record<string, unknown> | undefined,
): string {
  return typeof overData?.columnId === 'string' ? overData.columnId : parseColumnId(overId)
}

export function findCardLocation<TCard>(
  columns: KanbanColumnData<TCard>[],
  cardDragId: string,
  getCardDragId: (card: TCard) => UniqueIdentifier,
): CardLocation<TCard> | undefined {
  for (const [columnIndex, column] of columns.entries()) {
    const cardIndex = column.cards.findIndex((card) => String(getCardDragId(card)) === cardDragId)

    if (cardIndex !== -1) {
      return {
        card: column.cards[cardIndex]!,
        cardIndex,
        columnId: column.id,
        columnIndex,
      }
    }
  }
}

export function findCardInsertIndex<TCard>(
  columns: KanbanColumnData<TCard>[],
  targetColumnId: string,
  overId: UniqueIdentifier,
  getCardDragId: (card: TCard) => UniqueIdentifier,
  insertAfter = false,
): number | undefined {
  const targetColumn = columns.find((column) => column.id === targetColumnId)
  if (!targetColumn) return undefined

  if (parseColumnId(overId) === targetColumnId) return targetColumn.cards.length

  const overCardIndex = targetColumn.cards.findIndex(
    (card) => String(getCardDragId(card)) === String(overId),
  )

  if (overCardIndex === -1) return targetColumn.cards.length
  return overCardIndex + Number(insertAfter)
}

export function moveCardToPreviewColumn<TCard>(
  columns: KanbanColumnData<TCard>[],
  activeDragId: string,
  targetColumnId: string,
  overId: UniqueIdentifier,
  getCardDragId: (card: TCard) => UniqueIdentifier,
  insertAfter = false,
): KanbanColumnData<TCard>[] {
  const sourceLocation = findCardLocation(columns, activeDragId, getCardDragId)
  if (!sourceLocation || sourceLocation.columnId === targetColumnId) return columns

  const targetColumnIndex = columns.findIndex((column) => column.id === targetColumnId)
  if (targetColumnIndex === -1) return columns

  const targetColumn = columns[targetColumnIndex]!
  const targetIndex = findCardInsertIndex(
    columns,
    targetColumnId,
    overId,
    getCardDragId,
    insertAfter,
  )
  const boundedTargetIndex = Math.max(
    0,
    Math.min(targetIndex ?? targetColumn.cards.length, targetColumn.cards.length),
  )
  const previewColumns = columns.map((column) => ({ ...column, cards: [...column.cards] }))

  previewColumns[sourceLocation.columnIndex]!.cards.splice(sourceLocation.cardIndex, 1)
  previewColumns[targetColumnIndex]!.cards.splice(boundedTargetIndex, 0, sourceLocation.card)

  return previewColumns
}

interface ResolveCardMoveOptions<TCard> {
  activeDragId: string
  columns: KanbanColumnData<TCard>[]
  getCardDragId: (card: TCard) => UniqueIdentifier
  overData: Record<string, unknown> | undefined
  overId: UniqueIdentifier
  sourceColumnId?: string | null
  visibleColumns: KanbanColumnData<TCard>[]
}

export function resolveCardMove<TCard>({
  activeDragId,
  columns,
  getCardDragId,
  overData,
  overId,
  sourceColumnId,
  visibleColumns,
}: ResolveCardMoveOptions<TCard>): KanbanCardMove<TCard> | undefined {
  const sourceLocation = findCardLocation(columns, activeDragId, getCardDragId)
  if (!sourceLocation) return undefined

  const previewLocation = findCardLocation(visibleColumns, activeDragId, getCardDragId)
  const resolvedSourceColumnId = sourceColumnId || sourceLocation.columnId
  const targetColumnId = resolveTargetColumnId(overId, overData) || previewLocation?.columnId

  if (!targetColumnId || targetColumnId === resolvedSourceColumnId) return undefined
  const targetIndex =
    previewLocation?.columnId === targetColumnId
      ? previewLocation.cardIndex
      : findCardInsertIndex(visibleColumns, targetColumnId, overId, getCardDragId)

  return {
    card: sourceLocation.card,
    cardId: parseCardDragId(activeDragId),
    sourceColumnId: resolvedSourceColumnId,
    sourceIndex: sourceLocation.cardIndex,
    targetColumnId,
    targetIndex,
  }
}

export interface KanbanColumnData<TCard = unknown> {
  id: string
  title: string
  count: number
  cards: TCard[]
}

export interface KanbanCardMove<TCard = unknown> {
  card: TCard
  cardId: string
  sourceColumnId: string
  sourceIndex?: number
  targetColumnId: string
  targetIndex?: number
}

export interface KanbanStageOption {
  label: string
  value: string
}

import { type ClassValue, clsx } from 'clsx'
import { twMerge } from 'tailwind-merge'

export function cn(...inputs: ClassValue[]): string {
  return twMerge(clsx(inputs))
}
